                    sys.stderr.write(f'invalid value "{val}" for flag -{raw}: parse error\n')
                    sys.stderr.write(HELP)
                    raise SystemExit(2)
            else:
                if raw=='file': opts.file=val
                elif raw=='follow-output': opts.follow_output=val
                elif raw=='compare': opts.compare=val
                elif raw=='trimpath': opts.trimpath=val
                elif raw=='sort': opts.sort=val
                elif raw=='format': opts.fmt=val
