# ---------- formatting helpers ----------
def vis_len(s: str) -> int:
    # Good enough for Go test identifiers and ANSI. Treat wide symbols in markdown conservatively.
    return len(ANSI_RE.sub('', s))

def align_text(s: str, width: int, mode: str='left') -> str:
    l = vis_len(s)
    if l >= width:
        return s
    d = width-l
    if mode == 'right':
        return ' '*d + s
    if mode == 'center':
        left = d//2
        right = d-left
        return ' '*left + s + ' '*right
    return s + ' '*d

def color_status(st: str, opts: Opts, markdown=False) -> str:
    if not st:
        return ''
    if markdown and not opts.nocolor:
        return EMOJI.get(st, st)
    if opts.nocolor:
        return st
    a,b = C.get(st, ('',''))
    return a + st + b if a else st

def display_pkg(pkg: str, opts: Opts, small=False) -> str:
    s = pkg
    if opts.trimpath and s.startswith(opts.trimpath):
        s = s[len(opts.trimpath):]
    if small or opts.smallscreen:
        if '/' in s:
            s = s.rstrip('/').split('/')[-1]
    return s

def split_test_name(name: str, opts: Opts) -> str:
    if not opts.smallscreen:
        return name
    if len(name) < 45 or '/' not in name:
        return name
    parts = name.split('/')
    lines = [parts[0]]
    for p in parts[1:]:
        lines.append(' /' + p)
    return '\n'.join(lines)

def fmt_elapsed(x: float, suffix=False) -> str:
    return f'{x:.2f}' + ('s' if suffix else '')

def render_table(headers: List[str], rows: List[List[str]], aligns: Optional[List[str]]=None, fmt='basic') -> str:
    if aligns is None:
        aligns = ['left']*len(headers)
    # Split multiline cells.
    split_rows = []
    widths = [vis_len(h) for h in headers]
    for row in rows:
        sr=[]
        for j, cell in enumerate(row):
            lines = str(cell).split('\n') if str(cell)!='' else ['']
            sr.append(lines)
            for line in lines:
                widths[j] = max(widths[j], vis_len(line))
        split_rows.append(sr)
    out=[]
    if fmt == 'markdown':
        out.append('|' + '|'.join(' '+align_text(headers[i], widths[i], 'center')+' ' for i in range(len(headers))) + '|')
        out.append('|' + '|'.join('-'*(widths[i]+2) for i in range(len(headers))) + '|')
        for sr in split_rows:
            n=max(len(c) for c in sr)
            for k in range(n):
                cells=[]
                for j,c in enumerate(sr):
                    val = c[k] if k < len(c) else ''
                    cells.append(' '+align_text(val, widths[j], aligns[j])+' ')
                out.append('|' + '|'.join(cells) + '|')
        return '\n'.join(out)+'\n'
    if fmt == 'plain':
        def line(cells, header=False):
            pieces=[]
            for i,cell in enumerate(cells):
                mode = 'center' if header else aligns[i]
                pieces.append(' '+align_text(cell, widths[i], mode)+' ')
            return ' '.join(pieces)
        out.append(line(headers, True))
        out.append(line(['']*len(headers)))
        for sr in split_rows:
            n=max(len(c) for c in sr)
            for k in range(n):
                vals=[(sr[j][k] if k < len(sr[j]) else '') for j in range(len(headers))]
                out.append(line(vals))
        return '\n'.join(out)+'\n'
    # basic rounded unicode table
    top = '╭' + '┬'.join('─'*(w+2) for w in widths) + '╮'
    mid = '├' + '┼'.join('─'*(w+2) for w in widths) + '┤'
    bot = '╰' + '┴'.join('─'*(w+2) for w in widths) + '╯'
    out.append(top)
    out.append('│' + '│'.join(' '+align_text(headers[i], widths[i], 'center')+' ' for i in range(len(headers))) + '│')
    out.append(mid)
    for sr in split_rows:
        n=max(len(c) for c in sr)
        for k in range(n):
            cells=[]
            for j,c in enumerate(sr):
                val = c[k] if k < len(c) else ''
                cells.append(' '+align_text(val, widths[j], aligns[j])+' ')
            out.append('│' + '│'.join(cells) + '│')
    out.append(bot)
    return '\n'.join(out)+'\n'

# ---------- parse event stream ----------
def read_lines(opts: Opts) -> List[str]:
    if opts.file:
        try:
            with open(opts.file, 'r', encoding='utf-8', errors='replace') as f:
                return f.readlines()
        except OSError as e:
            sys.stderr.write(str(e)+'\n')
            raise SystemExit(1)
    # original insists on a pipe, not a terminal or plain redirected file
    try:
        mode = os.fstat(0).st_mode
        if not stat.S_ISFIFO(mode):
            sys.stderr.write('stdin must be a pipe, or use -file to open a go test output file\n')
            raise SystemExit(1)
    except SystemExit:
        raise
    except Exception:
        pass
    return sys.stdin.readlines()

def get_pkg(pkgs: Dict[str,PackageInfo], order: List[str], name: str) -> PackageInfo:
    if name not in pkgs:
        pkgs[name] = PackageInfo(name=name, order=len(order))
        order.append(name)
    return pkgs[name]

def get_test(p: PackageInfo, name: str) -> TestInfo:
    if name not in p.tests:
        p.tests[name] = TestInfo(name=name, package=p.name, order=len(p.test_order))
        p.test_order.append(name)
    return p.tests[name]

def parse_stream(lines: List[str], opts: Opts, follow_writer=None) -> Tuple[Dict[str,PackageInfo], List[str]]:
    pkgs: Dict[str,PackageInfo] = {}
    order: List[str] = []
    valid = 0
    coverage_re = re.compile(r'coverage:\s*([0-9]+(?:\.[0-9]+)?%)')
    reason_re = re.compile(r'(\[[^\]]*(?:no test files|no tests to run|no tests)[^\]]*\])')
    for line in lines:
        if not line.strip():
            continue
        try:
            ev = json.loads(line)
        except Exception:
            raise ParseError()
        if not isinstance(ev, dict):
            raise ParseError()
        action = str(ev.get('Action',''))
        pkgname = str(ev.get('Package',''))
        testname = str(ev.get('Test',''))
        if not action:
            continue
        valid += 1
        if not pkgname:
            continue
        p = get_pkg(pkgs, order, pkgname)
        if action == 'output':
            out = str(ev.get('Output',''))
            if testname:
                t = get_test(p, testname)
                t.outputs.append(out)
            else:
                p.outputs.append(out)
            m = coverage_re.search(out)
            if m:
                p.coverage = m.group(1)
            m = reason_re.search(out)
            if m:
                p.no_test_reason = m.group(1)
            if 'panic:' in out:
                p.panic = True
            if follow_writer is not None and not testname:
                # Follow useful package-level go test result lines, not bare PASS/FAIL/coverage chatter.
                stripped = out.strip('\n')
                if stripped and stripped not in ('PASS','FAIL') and not stripped.startswith('coverage:') and not stripped.startswith('# '):
                    prefix = ''
                    if opts.include_timestamp and ev.get('Time'):
                        prefix = str(ev.get('Time')) + ' '
                    follow_writer.write(prefix + out)
        elif action in ('pass','fail','skip'):
            elapsed = ev.get('Elapsed', 0.0)
            try:
                elapsed = float(elapsed)
            except Exception:
                elapsed = 0.0
            if testname:
                t = get_test(p, testname)
                t.status = action.upper()
                t.elapsed = elapsed
            else:
                p.status_action = action
                p.elapsed = elapsed
    if valid == 0:
        raise ParseError()
    return pkgs, order

# ---------- summarization ----------
def pkg_counts(p: PackageInfo) -> Tuple[int,int,int]:
    pa=fa=sk=0
    for name in p.test_order:
        st = p.tests[name].status
        if st == 'PASS': pa += 1
        elif st == 'FAIL': fa += 1
        elif st == 'SKIP': sk += 1
    return pa,fa,sk

def pkg_status(p: PackageInfo) -> str:
    pa,fa,sk = pkg_counts(p)
    if p.panic:
        return 'PANIC'
    if p.no_test_reason:
        return 'NOTEST'
    if p.status_action == 'fail' or fa > 0:
        return 'FAIL'
    if p.status_action == 'pass' or pa > 0 or sk > 0:
        return 'PASS'
    if p.status_action == 'skip':
        return ''
    return p.status_action.upper() if p.status_action else ''

def include_pkg(p: PackageInfo, opts: Opts) -> bool:
    if p.no_test_reason == '[no test files]' and not opts.notests:
        return False
    return True

def sort_pkg_names(pkgs: Dict[str,PackageInfo], order: List[str], opts: Opts) -> List[str]:
    names = [n for n in order if include_pkg(pkgs[n], opts)]
    if opts.sort == 'elapsed':
        names.sort(key=lambda n: (-pkgs[n].elapsed, n))
    elif opts.sort == 'cover':
        def cov(n):
            c=pkgs[n].coverage
            try: return -float(c.rstrip('%'))
            except Exception: return 1e9
        names.sort(key=lambda n: (cov(n), n))
    else:
        names.sort(key=lambda n: display_pkg(n, opts, False))
    return names

def test_rows_for_pkg(p: PackageInfo, opts: Opts) -> List[TestInfo]:
    show_table = opts.all or opts.show_pass or opts.show_skip
    if not show_table:
        return []
    tests=[]
    for name in p.test_order:
        t=p.tests[name]
        st=t.status
        want = False
        if opts.all and st in ('PASS','SKIP','FAIL'):
            want=True
        if opts.show_pass and st == 'PASS':
            want=True
        if opts.show_skip and st == 'SKIP':
            want=True
        if (opts.show_pass or opts.show_skip or opts.all) and st == 'FAIL':
            want=True
        if want:
            tests.append(t)
    if opts.slow > 0 and len(tests) > opts.slow:
        tests = sorted(tests, key=lambda t: -t.elapsed)[:opts.slow]
        # match observed grouping: slowest selected are shown slowest-first within a package
    return tests

# ---------- output pieces ----------
def render_test_table(pkgs, order, opts) -> str:
    names = sort_pkg_names(pkgs, order, opts)
    rows=[]
    first=True
    for n in names:
        p=pkgs[n]
        trs=test_rows_for_pkg(p, opts)
        if not first:
            rows.append(['','','',''])
        first=False
        for t in trs:
            rows.append([color_status(t.status, opts), fmt_elapsed(t.elapsed), split_test_name(t.name, opts), display_pkg(n, opts, opts.smallscreen)])
    # Drop a leading blank if there were no tests at all.
    while rows and rows[0] == ['','','','']:
        rows.pop(0)
    if not rows:
        return ''
    return render_table(['Status','Elapsed','Test','Package'], rows, ['center','center','left','left'], opts.fmt)

def render_pkg_table(pkgs, order, opts) -> str:
    rows=[]
    for n in sort_pkg_names(pkgs, order, opts):
        p=pkgs[n]
        st = pkg_status(p)
        pa,fa,sk = pkg_counts(p)
        disp = display_pkg(n, opts, opts.smallscreen)
        elapsed = 0.0 if st == 'PANIC' else p.elapsed
        if st in ('PANIC','NOTEST'):
            counts = ['--','--','--']
        else:
            counts = [str(pa), str(fa), str(sk)]
        pkgcell = disp
        if st == 'NOTEST' and p.no_test_reason:
            pkgcell = disp + '\n' + p.no_test_reason
        rows.append([color_status(st, opts), fmt_elapsed(elapsed, True), pkgcell, p.coverage, *counts])
    if not rows:
        return ''
    return render_table(['Status','Elapsed','Package','Cover','Pass','Fail','Skip'], rows,
                        ['center','center','left','center','center','center','center'], opts.fmt)

def normalized_output_line(s: str) -> str:
    # Go test output often includes tabs; tparse displays them expanded in panic/failure blocks.
    return s.rstrip('\n').replace('\t', '    ')

def fail_detail_for_test(t: TestInfo) -> str:
    lines=[]
    fail_lines=[]
    other=[]
    for raw in t.outputs:
        line = normalized_output_line(raw)
        if not line or line.startswith('=== RUN'):
            continue
        if line.startswith('--- FAIL:') or line.startswith('--- FAIL'):
            fail_lines.append(line)
        elif line.startswith('--- PASS:') or line.startswith('--- SKIP:'):
            continue
        else:
            other.append(line)
    if not fail_lines:
        fail_lines = [f'--- FAIL: {t.name} ({t.elapsed:.2f}s)']
    lines.extend(fail_lines)
    lines.append('')
    lines.extend(other)
    lines.append('')
    return '\n'.join(lines)+'\n'

def render_banner(kind: str, pkg: str, test: Optional[str], opts: Opts) -> str:
    st = color_status(kind, opts)
    title_plain = f'   {kind}  package: {pkg}' + (f' • {test}' if test else '') + '   '
    title = f'   {st}  package: {pkg}' + (f' • {test}' if test else '') + '   '
    w = vis_len(title_plain)
    if opts.nocolor:
        return '┏'+'━'*w+'┓\n'+'┃'+title+'┃\n'+'┗'+'━'*w+'┛\n'
    bc='\x1b[38;5;103m'; reset='\x1b[0m'
    return bc+'┏'+'━'*w+'┓'+reset+'\n'+bc+'┃'+reset+title+bc+'┃'+reset+'\n'+bc+'┗'+'━'*w+'┛'+reset+'\n'

def render_failures(pkgs, order, opts) -> str:
    out=[]
    for n in sort_pkg_names(pkgs, order, opts):
        p=pkgs[n]
        if pkg_status(p) != 'FAIL':
            continue
        failed=[p.tests[t] for t in p.test_order if p.tests[t].status=='FAIL']
        if not failed:
            continue
        if opts.fmt == 'markdown':
            out.append(f'## {color_status("FAIL", opts, markdown=True)} • {display_pkg(n, opts, False)}\n\n```\n')
            for i,t in enumerate(failed):
                if i:
                    out.append('\n'+'─'*96+'\n\n')
                out.append(fail_detail_for_test(t))
            out.append('```\n\n')
        else:
            out.append(render_banner('FAIL', display_pkg(n, opts, False), None, opts))
            out.append('\n')
            for i,t in enumerate(failed):
                if i:
                    out.append('─'*96+'\n\n')
                out.append(fail_detail_for_test(t))
    return ''.join(out)

def render_panics(pkgs, order, opts) -> str:
    out=[]
    for n in sort_pkg_names(pkgs, order, opts):
        p=pkgs[n]
        if pkg_status(p) != 'PANIC':
            continue
        testname = None
        for tn in p.test_order:
            if any('panic:' in x for x in p.tests[tn].outputs):
                testname = tn; break
        if opts.fmt == 'markdown':
            out.append(f'## {color_status("PANIC", opts, markdown=True)} • {display_pkg(n, opts, False)}\n\n```\n')
        else:
            out.append(render_banner('PANIC', display_pkg(n, opts, False), testname, opts))
        lines=[]
        if testname:
            for raw in p.tests[testname].outputs:
                line=normalized_output_line(raw)
                if line.startswith('=== RUN') or not line:
                    continue
                lines.append(line)
        else:
            for raw in p.outputs:
                line=normalized_output_line(raw)
                if line:
                    lines.append(line)
        # Include package-level FAIL line too for test panics.
        if testname:
            for raw in p.outputs:
                line=normalized_output_line(raw)
                if line.startswith('FAIL'):
                    lines.append(line)
        out.append('\n'.join(lines)+'\n')
        if opts.fmt == 'markdown':
            out.append('```\n\n')
        else:
            out.append('\n')
    return ''.join(out)

def render_markdown_test_sections(pkgs, order, opts) -> str:
    parts=[]
    for n in sort_pkg_names(pkgs, order, opts):
        p=pkgs[n]
        trs=test_rows_for_pkg(p, opts)
        if not trs:
            continue
        pa,fa,sk = pkg_counts(p)
        pkgd = display_pkg(n, opts, opts.smallscreen)
        parts.append(f'## 📦 Package **`{pkgd}`**\n\n')
        parts.append(f'Tests: ✓ {pa} passed | {sk} skipped | {fa} failed\n\n')
        parts.append('<details>\n\n<summary>Click for test summary</summary>\n\n')
        rows=[]
        for t in trs:
            rows.append([color_status(t.status, opts, markdown=True), fmt_elapsed(t.elapsed), split_test_name(t.name, opts)])
        parts.append(render_table(['Status','Elapsed','Test'], rows, ['center','center','left'], 'markdown'))
        parts.append('</details>\n\n\n')
    return ''.join(parts)

def print_progress(pkgs, order, opts):
    if not opts.progress:
        return
    for n in order:
        p=pkgs[n]
        if not include_pkg(p, opts):
            continue
        st=pkg_status(p)
        if not st or st=='NOTEST':
            continue
        sys.stdout.write(f'[{color_status(st, opts)}]\t{fmt_elapsed(0.0 if st=="PANIC" else p.elapsed, True):>9}\t{display_pkg(n, opts, False)}\n')

# ---------- main ----------
def main(argv):
    opts=parse_args(argv)
    lines=read_lines(opts)
    follow_writer=None
    fobj=None
    if opts.follow_output:
        try:
            fobj=open(opts.follow_output,'w',encoding='utf-8')
            follow_writer=fobj
        except OSError as e:
            sys.stderr.write(str(e)+'\n')
            raise SystemExit(1)
    elif opts.follow:
        follow_writer=sys.stdout
    # Compare file is deliberately best-effort, matching observed warning-only behavior.
    if opts.compare:
        try:
            with open(opts.compare,'r',encoding='utf-8',errors='replace') as cf:
                _=cf.read(1)
        except OSError:
            sys.stderr.write(f'warning: failed to open against file: {opts.compare}\n')
    try:
        pkgs, order = parse_stream(lines, opts, follow_writer)
    except ParseError:
        sys.stderr.write('no parsable events: Make sure to run go test with -json flag\n')
        raise SystemExit(1)
    finally:
        if fobj: fobj.close()
    print_progress(pkgs, order, opts)
    show_test = opts.all or opts.show_pass or opts.show_skip
    if opts.fmt == 'markdown':
        if show_test:
            sys.stdout.write(render_markdown_test_sections(pkgs, order, opts))
        sys.stdout.write(render_panics(pkgs, order, opts))
        sys.stdout.write(render_failures(pkgs, order, opts))
        sys.stdout.write(render_pkg_table(pkgs, order, opts))
    else:
        if show_test:
            sys.stdout.write(render_test_table(pkgs, order, opts))
        sys.stdout.write(render_panics(pkgs, order, opts))
        sys.stdout.write(render_failures(pkgs, order, opts))
        sys.stdout.write(render_pkg_table(pkgs, order, opts))
    # Fail if any package failed or panicked.
    for p in pkgs.values():
        if pkg_status(p) in ('FAIL','PANIC'):
            raise SystemExit(1)
    raise SystemExit(0)

if __name__ == '__main__':
    main(sys.argv[1:])
